def _decode_embedded_source(payload):
    return zlib.decompress(base64.b64decode(payload.encode("ascii"))).decode("utf-8")

DEFAULT_BOX_CENTER_Y = 0.238
__all__ = ["grasp_object", "place_object"]


def _get_value(source, name, default):
    if source is None:
        return default
    if isinstance(source, dict):
        return source.get(name, default)
    return getattr(source, name, default)


def _as_world_vector(value, label):
    if value is None:
        return None
    array = np.asarray(value, dtype=float).reshape(-1)
    if array.size != 3:
        raise ValueError(f"{label} must have exactly 3 values")
    return array


def choose_scene_params(seed, dy_range, fixed_dy, layer_min, layer_max, fixed_layer):
    actual_seed = random.randrange(0, 2**31) if seed is None else int(seed)
    rng = random.Random(actual_seed)
    box_dy = (
        float(fixed_dy)
        if fixed_dy is not None
        else rng.uniform(-float(dy_range), float(dy_range))
    )
    box_layer = (
        int(fixed_layer)
        if fixed_layer is not None
        else int(rng.randint(int(layer_min), int(layer_max)))
    )
    return actual_seed, box_dy, box_layer


def _exec_embedded_source(source_text, module_name):
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    module.__package__ = ""
    module.__dict__["__builtins__"] = __builtins__
    sys.modules[module_name] = module
    try:
        exec(compile(source_text, module.__file__, "exec"), module.__dict__)
    except Exception:
        sys.modules.pop(module_name, None)
        raise
    return module


