def load_return_to_shelf_box_pick():
    patched_text = _decode_embedded_source(EMBEDDED_RETURN_TO_SHELF_B64)
    import_block = (
        "    from wam_critic import WAMCritic, WAMCriticRecorder\n"
        "    from action_wam import ActionWAMCritic\n"
        "    from visual_wam import VisualWAMCritic, VisualWAMRecorder\n"
    )
    import_replacement = (
        "    try:\n"
        "        from wam_critic import WAMCritic, WAMCriticRecorder\n"
        "        from action_wam import ActionWAMCritic\n"
        "        from visual_wam import VisualWAMCritic, VisualWAMRecorder\n"
        "    except Exception:\n"
        "        class _MissingWAMSupport:\n"
        "            legacy_transport_labels = False\n"
        "            def __init__(self, *args, **kwargs):\n"
        "                pass\n"
        "            def add(self, *args, **kwargs):\n"
        "                return None\n"
        "            def flush(self, *args, **kwargs):\n"
        "                return None\n"
        "            def predict(self, *args, **kwargs):\n"
        "                return {'safe': 0.0, 'four_finger_contact': 0.0, 'transport_ready': 0.0, 'slot_ready': 0.0}\n"
        "        WAMCritic = _MissingWAMSupport\n"
        "        WAMCriticRecorder = _MissingWAMSupport\n"
        "        ActionWAMCritic = _MissingWAMSupport\n"
        "        VisualWAMCritic = _MissingWAMSupport\n"
        "        VisualWAMRecorder = _MissingWAMSupport\n"
    )
    if import_block in patched_text:
        patched_text = patched_text.replace(import_block, import_replacement, 1)

    return _exec_embedded_source(
        patched_text,
        f"_box_pick_return_to_shelf_runtime_{random.randrange(1 << 30)}",
    )


def grasp_object(env, target_world, grasp_world=None):
    """
    输入:
        env         : 当前已经运行的 DISCOVERSE 环境
        target_world : 目标物世界坐标 [x, y, z]
        grasp_world  : 推荐抓取点世界坐标 [x, y, z]

    输出:
        True  : 成功抓取
        False : 抓取失败
    """
    target_world_vec = _as_world_vector(target_world, "target_world")
    grasp_world_vec = _as_world_vector(grasp_world, "grasp_world")

    mjcf_path = _get_value(env, "mjcf_path", DEFAULT_MJCF_FILE_PATH)
    discoverse_root = _get_value(env, "discoverse_root", DEFAULT_DISCOVERSE_ROOT)
    urdf_path = _get_value(env, "urdf_path", DEFAULT_URDF_PATH)
    scene_seed = _get_value(env, "scene_seed", None)
    dy_range = float(_get_value(env, "dy_range", 0.15))
    fixed_dy = _get_value(env, "fixed_dy", None)
    layer_min = max(3, int(_get_value(env, "layer_min", 3)))
    layer_max = min(4, int(_get_value(env, "layer_max", 4)))
    fixed_layer = _get_value(env, "fixed_layer", None)
    headless_preview_seconds = _get_value(env, "headless_preview_seconds", None)

    if fixed_dy is None and target_world_vec is not None:
        fixed_dy = float(np.clip(target_world_vec[1] - DEFAULT_BOX_CENTER_Y, -dy_range, dy_range))
    if fixed_layer is None:
        z_hint = None
        if grasp_world_vec is not None:
            z_hint = float(grasp_world_vec[2])
        elif target_world_vec is not None:
            z_hint = float(target_world_vec[2])
        if z_hint is not None:
            fixed_layer = 4 if z_hint >= 1.0 else 3

    seed, box_dy, box_layer = choose_scene_params(
        scene_seed,
        dy_range,
        fixed_dy,
        layer_min,
        layer_max,
        fixed_layer,
    )
    print(
        ">>> randomized scene: "
        f"seed={seed}, box_dy={box_dy:.4f}, box_layer={box_layer}, "
        f"dy_range={dy_range:.4f}, layer_range={layer_min}-{layer_max}"
    )
    print(
        ">>> base lateral alignment enabled: "
        f"target_dy={box_dy:+.4f}m, base will move before grasping"
    )
    print(
        ">>> grasp_object:",
        f"seed={seed}, box_dy={box_dy:.4f}, box_layer={box_layer}, "
        f"target_world={np.round(target_world_vec, 4).tolist() if target_world_vec is not None else None}, "
        f"grasp_world={np.round(grasp_world_vec, 4).tolist() if grasp_world_vec is not None else None}",
    )

    try:
        box_pick_runtime = load_base_align_box_pick(box_dy)
        return bool(
            box_pick_runtime.run_box_pick_grasp_scene(
                str(Path(mjcf_path)),
                discoverse_root,
                urdf_path=urdf_path,
                headless=headless_preview_seconds is not None,
                max_seconds=headless_preview_seconds,
                randomize_scene=False,
                randomize_box_pose=True,
                shelf_level=box_layer,
                scene_seed=seed,
            )
        )
    except Exception as exc:
        print(f">>> grasp_object failed: {type(exc).__name__}: {exc}")
        return False


def place_object(env, target_world, place_world=None):
    """
    输入:
        env         : 当前已经运行的 DISCOVERSE 环境
        target_world : 目标物世界坐标 [x, y, z]
        place_world  : 推荐放置点世界坐标 [x, y, z]

    输出:
        True  : 成功放置
        False : 放置失败
    """
    target_world_vec = _as_world_vector(target_world, "target_world")
    place_world_vec = _as_world_vector(place_world, "place_world")

    mjcf_path = _get_value(env, "mjcf_path", DEFAULT_MJCF_FILE_PATH)
    discoverse_root = _get_value(env, "discoverse_root", DEFAULT_DISCOVERSE_ROOT)
    urdf_path = _get_value(env, "urdf_path", DEFAULT_URDF_PATH)
    scene_seed = _get_value(env, "scene_seed", 0)
    randomize_scene = bool(_get_value(env, "randomize_scene", False))
    headless_preview_seconds = _get_value(env, "headless_preview_seconds", None)

    print(
        ">>> place_object:",
        f"seed={scene_seed}, "
        f"target_world={np.round(target_world_vec, 4).tolist() if target_world_vec is not None else None}, "
        f"place_world={np.round(place_world_vec, 4).tolist() if place_world_vec is not None else None}, "
        f"randomize_scene={randomize_scene}",
    )

    try:
        box_pick_runtime = load_return_to_shelf_box_pick()
        result = box_pick_runtime.run_box_pick_grasp_scene(
            str(Path(mjcf_path)),
            discoverse_root,
            urdf_path=urdf_path,
            headless=headless_preview_seconds is not None,
            max_seconds=headless_preview_seconds,
            randomize_scene=randomize_scene,
            scene_seed=int(scene_seed),
        )
        return True if result is None else bool(result)
    except Exception as exc:
        print(f">>> place_object failed: {type(exc).__name__}: {exc}")
        return False


def main():
    parser = argparse.ArgumentParser(
        description="Run box_pick with left/right box position randomized and the base aligned to the box."
    )
    parser.add_argument("--mjcf", default=DEFAULT_MJCF_FILE_PATH)
    parser.add_argument("--discoverse-root", default=DEFAULT_DISCOVERSE_ROOT)
    parser.add_argument("--urdf", default=DEFAULT_URDF_PATH)
    parser.add_argument("--scene-seed", type=int, default=None)
    parser.add_argument("--dy-range", type=float, default=0.15)
    parser.add_argument("--fixed-dy", type=float, default=None)
    parser.add_argument("--layer-min", type=int, default=3)
    parser.add_argument("--layer-max", type=int, default=4)
    parser.add_argument("--fixed-layer", type=int, default=None)
    parser.add_argument("--headless-preview-seconds", type=float, default=None)
    args = parser.parse_args()

    layer_min = max(3, int(args.layer_min))
    layer_max = min(4, int(args.layer_max))
    if layer_min > layer_max:
        raise ValueError("layer-min must be <= layer-max")

    success = grasp_object(args, None, None)
    raise SystemExit(0 if success else 1)


if __name__ == "__main__":
    main()
